const axios = require('axios');

const UPSTASH_URL   = $vars.upstash_url;
const UPSTASH_TOKEN = $vars.upstash_token;


// ── Upstash REST helpers ──────────────────────────────────────────────────────
async function redisCommand(...args) {
  const res = await axios.post(UPSTASH_URL, args, {
    headers: {
      Authorization: `Bearer ${UPSTASH_TOKEN}`,
      'Content-Type': 'application/json'
    }
  });
  return res.data.result;
}

async function redisGet(key) {
  return await redisCommand('GET', key);
}

async function redisSet(key, value, ttl) {
  return await redisCommand('SET', key, value, 'EX', ttl);
}

async function redisDel(key) {
  return await redisCommand('DEL', key);
}

async function redisScan(pattern) {
  return await redisCommand('SCAN', '0', 'MATCH', pattern, 'COUNT', '100');
}

// ── Main ──────────────────────────────────────────────────────────────────────
const answer = $input || '';
console.log('[Node2] Answer received:', answer.slice(0, 100));

if (!answer) {
  console.warn('[Node2] No answer, skipping');
  return $input;
}

try {
  // Find pending marker Node 1 wrote
  const scanResult = await redisScan('aep:pending:*');
  const keys = scanResult[1];

  if (!keys || keys.length === 0) {
    console.log('[Node2] No pending key — was a cache HIT, nothing to write');
    return $input;
  }

  const pendingKey = keys[0];
  const raw        = await redisGet(pendingKey);

  if (!raw) {
    console.warn('[Node2] Pending key expired, skipping');
    return $input;
  }

  const { key, ttl, query } = JSON.parse(raw);

  // Write answer to Redis
  await redisSet(key, JSON.stringify({
    query,
    answer,
    cachedAt: new Date().toISOString()
  }), ttl);

  // Delete pending marker
  await redisDel(pendingKey);

  console.log('[Node2] WRITE SUCCESS ✅');
  console.log('[Node2] Key:', key);
  console.log('[Node2] Query:', query);
  console.log('[Node2] TTL:', ttl, 'seconds');
  console.log('[Node2] Answer preview:', answer.slice(0, 100));

  // Verify write
  const verify = await redisGet(key);
  if (verify) {
    console.log('[Node2] VERIFIED in Redis ✅');
  } else {
    console.error('[Node2] VERIFICATION FAILED ❌');
  }

} catch (err) {
  console.warn('[Node2] Redis error:', err.message);
}

return $input;

