const axios = require('axios');
const crypto = require('crypto');

const UPSTASH_URL   = $vars.upstash_url;
const UPSTASH_TOKEN = $vars.upstash_token;


const TTL_POLICY  = 60 * 60 * 24;
const TTL_PRODUCT = 60 * 30;
const TTL_GENERAL = 60 * 60 * 6;
const TTL_FAQ     = 60 * 60 * 24 * 7;

async function redisCommand(...args) {
  const res = await axios.post(UPSTASH_URL, args, {
    headers: {
      Authorization: `Bearer ${UPSTASH_TOKEN}`,
      'Content-Type': 'application/json'
    }
  });
  return res.data.result;
}

async function redisGet(key) { return await redisCommand('GET', key); }
async function redisSet(key, value, ttl) { return await redisCommand('SET', key, value, 'EX', ttl); }
async function redisExpire(key, ttl) { return await redisCommand('EXPIRE', key, ttl); }

function normalise(text) {
  return text.toLowerCase().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').trim();
}

function cacheKey(query) {
  const hash = crypto.createHash('sha256').update(normalise(query)).digest('hex').slice(0, 16);
  return `aep:cache:${hash}`;
}

function pickTTL(query) {
  const q = query.toLowerCase();
  const policyTerms  = ['return','refund','cancel','exchange','warranty','shipping','payment','replace','policy'];
  const productTerms = ['product','price','stock','availability','catalogue','search'];
    const faqTerms     = ['ram','storage','5g','4g','amoled','lcd','refresh rate','fast charging','nfc','ip68','processor','mah','dual sim','power bank','usb-c','screen protector','earbuds','bluetooth','arch support','memory foam','moisture','slim fit','polyester','cotton','refurbished'];
  if (policyTerms.some(t => q.includes(t)))  return TTL_POLICY;
  if (productTerms.some(t => q.includes(t))) return TTL_PRODUCT;
  if (faqTerms.some(t => q.includes(t)))     return TTL_FAQ;
  return TTL_GENERAL;
}

const query = $input || '';
console.log('[Node1] Query:', query);

if (!query) return 'CACHE_MISS';

const key = cacheKey(query);
const ttl = pickTTL(query);

try {
  const cached = await redisGet(key);

  if (cached) {
    const parsed = JSON.parse(cached);
    await redisExpire(key, ttl);
    console.log('[Node1] CACHE HIT ✅ key:', key);
    console.log('[Node1] Answer:', parsed.answer.slice(0, 100));
    // Return the actual answer prefixed with CACHE_HIT marker
    return `CACHE_HIT::${parsed.answer}`;
  }

  // CACHE MISS — write pending marker
  const pendingKey = `aep:pending:${key}`;
  await redisSet(pendingKey, JSON.stringify({ key, ttl, query }), 300);
  console.log('[Node1] CACHE MISS ❌ key:', key);

} catch (err) {
  console.warn('[Node1] Error, failing open:', err.message);
}

return 'CACHE_MISS';

