inputs.customFunctionJavascriptFunction:
const axios = require('axios');

const BASE = 'http://localhost:3000';

const CHATFLOW_MAP = {
  product:   'e7b808c7-461c-461d-be49-38836cc04dfb',
  policy:    '4356e06a-6ffc-4e03-ab41-08a01ae0f62b',
  complaint: '8ea0806d-e675-412f-9e0c-4a52af7f774c',
  faq:       'fda0582f-8707-4ac6-8981-9fc0898c4c07',
  handoff:   'f14dcc14-777c-49e1-a2b2-fb1145aeba70',
  warranty:  '436ddb21-65a1-4640-b09f-089bbc4ac56a',
  tracking:  '3c573461-746b-448f-9752-ad9765f9b878'

};

// ── Escalation counter from flow state ───────────────────────────────────────
// $vars holds Flowise runtime state variables you define in Start node
let unresolvedCount = parseInt($vars?.unresolvedComplaintCount || '0');

// Parse decomposed intents
let decomposed = [];
try {
  const clean = $intentJson.trim().replace(/```json|```/g, '');
  decomposed = JSON.parse(clean).decomposed || [];
} catch(e) {
  decomposed = [{ intent: 'product', query: $userQuery }];
}

if (!decomposed.length) {
  decomposed = [{ intent: 'product', query: $userQuery }];
}

// ── Explicit handoff intent (user directly asked for human) ──────────────────
const handoffItem = decomposed.find(d => d.intent === 'handoff');
if (handoffItem) {
  const res = await axios.post(
    `${BASE}/api/v1/prediction/${CHATFLOW_MAP.handoff}`,
    { question: handoffItem.query },
    { headers: { 'Content-Type': 'application/json' } }
  );
  const answer = res.data.text || res.data.answer || '';
  return `HANDOFF::${answer}`;
}

// ── Auto-escalation: increment counter if this turn is complaint-only ────────
const intentsThisTurn = decomposed.map(d => d.intent);
const isComplaintOnlyTurn = intentsThisTurn.every(i => i === 'complaint' || i === 'policy');
const hasProductIntent = intentsThisTurn.includes('product');

if (isComplaintOnlyTurn && !hasProductIntent) {
  unresolvedCount += 1;
} else {
  // Customer started shopping again — reset the counter
  unresolvedCount = 0;
}

// Store updated count back to flow state
// This requires agentUpdateState wired on the Fan-out node (see Fix 2 below)
$flow.state = { ...$flow.state, unresolvedComplaintCount: String(unresolvedCount) };

// ── Auto-escalation threshold: 3 unresolved complaint turns ─────────────────
if (unresolvedCount >= 3) {
  const res = await axios.post(
    `${BASE}/api/v1/prediction/${CHATFLOW_MAP.handoff}`,
    { question: $userQuery },
    { headers: { 'Content-Type': 'application/json' } }
  );
  const answer = res.data.text || res.data.answer || '';
  // Reset counter after handoff
  $flow.state = { ...$flow.state, unresolvedComplaintCount: '0' };
  return `HANDOFF::${answer}`;
}

// ── Normal parallel execution ─────────────────────────────────────────────────
const calls = decomposed
  .filter(d => d.intent !== 'handoff' && CHATFLOW_MAP[d.intent])
  .map(async ({ intent, query }) => {
    try {
      const res = await axios.post(
        `${BASE}/api/v1/prediction/${CHATFLOW_MAP[intent]}`,
        { question: query },
        { headers: { 'Content-Type': 'application/json' } }
      );
      const text = res.data.text || res.data.answer || '';
      return `###INTENT:${intent.toUpperCase()}\n${text}`;
    } catch(err) {
      return `###INTENT:${intent.toUpperCase()}\nERROR: Could not retrieve ${intent} information.`;
    }
  });

const results = await Promise.all(calls);
return results.join('\n\n');

